function detectOrderBookAnomaly(currentDepth, historicalDepths) {
// 计算当前深度与历史平均值的差异
const avgBidDepth = calculateAverageDepth(historicalDepths.bids);
const avgAskDepth = calculateAverageDepth(historicalDepths.asks);

const bidDeviation = Math.abs(currentDepth.bids - avgBidDepth) / avgBidDepth;
const askDeviation = Math.abs(currentDepth.asks - avgAskDepth) / avgAskDepth;

// 如果偏差超过阈值，触发警报
if (bidDeviation > 0.4 || askDeviation > 0.4) {
return {
anomalyDetected: true,
type: bidDeviation > askDeviation ? 'BID_ANOMALY' : 'ASK_ANOMALY',
severity: Math.max(bidDeviation, askDeviation)
};
}

return { anomalyDetected: false };
}

